import{z as l,x as A,o as t,c as d,q as n,j as s,D as E,d as r,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"盘前盘后交易","description":"","frontmatter":{"title":"盘前盘后交易","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pre-post-market.md","filePath":"quant/pre-post-market.md","lastUpdated":1791413859000}'),p={name:"quant/pre-post-market.md"};function D(c,a,m,h,u,f){const B=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=n('<h1 id="盘前盘后交易" tabindex="-1">盘前盘后交易 <a class="header-anchor" href="#盘前盘后交易" aria-label="Permalink to &quot;盘前盘后交易&quot;">​</a></h1><div class="epigraph"><p>官方收盘价是合同锚，不是发现的终点。锚钉住之后，更薄、更暗、更少保护的时段仍在交易；价格发现会迁到那些时段，流动性却不必一起迁过去。</p><footer>—— Barclay and Hendershott, Price discovery and trading after hours, Review of Financial Studies, 2003</footer></div><p><a href="/quant/circuit-breaker-design">熔断</a> 管的是常规连续时段如何停机。<a href="/quant/closing-auction-design">收盘竞价</a> 已经警告：盘后若继续交易，「收盘」只是会计时刻。缺口是盘前盘后（extended hours）本身：谁在交易、价差为何更宽、发现份额为何可以很高。Barclay 与 Hendershott（2003, 2004）把盘后写成低量、高逆向选择、但信息含量不低的时段。本课写时段作为场所规则的一维，不重写收盘拍卖机制，也不把 24 小时外汇当成同一对象——外汇留给后课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>常规时段有保护报价、LULD、做市义务与厚的噪声流。盘前盘后常常：参与场所更少、订单保护与熔断带宽不适用或弱化、批发商与暗处占比更高、展示深度更薄。盈余公告、宏观数据、指数再平衡的信息大量落在这个时钟上。于是出现分裂：发现可以发生在盘后（中点随后不再回复），流动性却极差（有效价差与冲击远大于日间）。问题是如何同时读这两张表，以及官方收盘价作为公共品，如何被盘后打印「修正」却不必改写合同。</p><p><span class="marginnote">盘前盘后的术语翻译：美股常规时段是 9:30–16:00，之外的盘前（约 4:00 起）与盘后（到 20:00）仍可交易，但规则降级——订单保护、熔断、做市义务往往不覆盖。像「加油站下班后的自助泵」：油还能加，服务台没人。</span></p><p>Barclay–Hendershott 的流动性外部性在此更尖：人少则价差宽，价差宽则更多人等到开盘，薄的均衡可以自我维持。强制把发现赶到开盘拍卖，与允许盘后交易，是两种分配。</p><h3 id="公告窗与不可保护的报价" tabindex="-1">公告窗与不可保护的报价 <a class="header-anchor" href="#公告窗与不可保护的报价" aria-label="Permalink to &quot;公告窗与不可保护的报价&quot;">​</a></h3><p>许多公司把盈余放到常规收盘之后。盘后第一笔打印可以是信息，也可以是过薄簿上的噪声。没有完整 NMS 保护时，穿过、锁定、过时报价更常见；<a href="/quant/sip-vs-direct">SIP 与直连</a> 的时钟差在参与者更少时反而更刺眼。LULD 若未覆盖，错误 tick 要靠经纪商风控而不是全国带宽。把盘后成交当「与日间同样可执行的 NBBO 对照」，会系统性低估成本。</p><p><span class="marginnote">A 股没有美股式延长时段连续簿；接近的是盘后固定价格与大宗。名称不能翻译，制度对象先对齐。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分时段构造：成交量、有效价差、实现价差、Hasbrouck 信息份额或加权价格贡献、以及相对次日开盘的回复。发现高而流动性差，是盘后的典型签名，不是数据错误。事件研究以公告时戳分「落入延长时段 / 落入开盘拍卖 / 落入日间」，不要用日历日把盘后打印并进收盘价。对照官方收盘与 16:00 之后一段时间的中点，差额是「合同锚 vs 继续发现」。</p><p><span class="marginnote">数字实例：盈余公告 16:05 发布，盘后第一笔成交 102.5 美元、价差 1 美元，次日开盘拍卖落在 103.2 美元。若事件研究只按官方收盘 100 美元计收益，会整个漏掉「信息在盘后已被定价 2.5%」——公告时戳落在哪个时段，决定结论对错。</span></p><p>与零售：部分零售经纪商有限开放盘前盘后，流的毒性结构与日间批发商内化不同。不要把 BJZZ 日间痕迹直接套到延长时段。</p>',14)),(t(),s(i,null,{default:E(()=>[o(B,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20LR%0A%20%20Close%5B%22%E5%AE%98%E6%96%B9%E6%94%B6%E7%9B%98%E9%94%9A%22%5D%20--%3E%20Contract%5B%22%E6%8C%87%E6%95%B0%20%2F%20%E5%9F%BA%E9%87%91%20%2F%20%E8%A1%8D%E7%94%9F%E5%93%81%E7%BB%93%E7%AE%97%22%5D%0A%20%20Close%20--%3E%20AH%5B%22%E7%9B%98%E5%90%8E%E7%BB%A7%E7%BB%AD%E5%8C%B9%E9%85%8D%22%5D%0A%20%20AH%20--%3E%20Disc%5B%22%E5%8F%91%E7%8E%B0%E5%8F%AF%E4%BB%A5%E8%BF%81%E7%A7%BB%22%5D%0A%20%20AH%20--%3E%20Liq%5B%22%E6%B7%B1%E5%BA%A6%E8%96%84%2C%20%E4%BF%9D%E6%8A%A4%E5%BC%B1%22%5D%0A%20%20Open%5B%22%E5%BC%80%E7%9B%98%E6%8B%8D%E5%8D%96%22%5D%20--%3E%20Catch%5B%22%E5%90%B8%E6%94%B6%E9%9A%94%E5%A4%9C%E6%AE%8B%E4%BD%99%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"延长时段接近经销商市场：参与者少、搜索成本高、存货不愿过夜，价差补偿逆向选择与库存。知情者相对更愿意在此交易（公告后立刻变现），噪声相对更愿意等开盘的厚批次——Easley–O'Hara 的事件日在钟面上被拉长。收盘拍卖解决的是合同同步，不解决公告后的发现；盘后解决发现，不提供日间那种公共深度。开盘拍卖再一次把隔夜订单聚成批次，暂时成分在开盘后被消化，永久成分留下。",-1)),a[5]||(a[5]=e("p",null,"对执行：必须在收盘拍卖完成的仓位，不应改到盘后去「补一点」；盘后 \\(\\lambda\\) 是另一市场。对冲若一边是日间期货、一边是盘后现货，基差含时段溢价，不是模型残差。",-1)),(t(),s(i,null,{default:E(()=>[o(B,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEW%5B%22%E5%8F%82%E4%B8%8E%E8%80%85%E5%B0%91%22%5D%20--%3E%20WIDE%5B%22%E4%BB%B7%E5%B7%AE%E5%AE%BD%E3%80%81%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%E5%A4%A7%22%5D%0A%20%20WIDE%20--%3E%20WAIT%5B%22%E5%99%AA%E5%A3%B0%E4%BA%A4%E6%98%93%E8%80%85%E7%AD%89%E5%88%B0%E5%BC%80%E7%9B%98%E5%8E%9A%E6%89%B9%E6%AC%A1%22%5D%0A%20%20WAIT%20--%3E%20FEW%0A%20%20INFO%5B%22%E5%85%AC%E5%91%8A%E8%90%BD%E5%9C%A8%E7%9B%98%E5%90%8E%22%5D%20--%3E%20TRADE%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E4%B8%BA%E5%8D%B3%E6%97%B6%E5%8F%98%E7%8E%B0%E4%BB%8D%E5%9C%A8%E4%BA%A4%E6%98%93%22%5D%0A%20%20TRADE%20--%3E%20ASYM%5B%22%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E7%9B%B8%E5%AF%B9%E5%8D%A0%E6%AF%94%E6%9B%B4%E9%AB%98%22%5D%0A%20%20ASYM%20--%3E%20WIDE%0A%20%20WIDE%20--%3E%20SIGN%5B%22%E7%9B%98%E5%90%8E%E7%AD%BE%E5%90%8D%EF%BC%9A%E5%8F%91%E7%8E%B0%E9%AB%98%20%2B%20%E6%B5%81%E5%8A%A8%E6%80%A7%E5%B7%AE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各所延长时段的可交易品种、订单类型、是否纳入官方价格统计，差异大。ETF 与成分股若一个可盘后、一个不可，篮子无法复制。下一课把「薄、双边议价、关系型对手方」从延长时段的弱形式，推到完整的场外经销商市场。</p><p><span class="marginnote">常见误区：初学者容易把盘后价差宽当成「数据错误」或「做市商贪婪」，实际上宽价差是对「参与者少、搜索成本高、可能撞上知情单」的合理补偿。薄而贵的市场不是坏掉的市场，是均衡的另一种样子。</span></p><p><span class="marginnote">用收盘价做日度因子，等于把盘后发现推迟到次日开盘。对公告日这是错的时间聚合，不是无害的惯例。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>盘前盘后可以承担发现、不必提供日间流动性；两张表必须分开。</li><li>保护、熔断与做市义务在延长时段往往弱化，有效成本不能对照日间 NBBO。</li><li>官方收盘是合同锚；盘后打印修正的是信息，不一定修正合同。</li><li>出处：Barclay and Hendershott, <em>RFS</em>, 2003；以及二人 <em>Journal of Finance</em>, 2004 对盘后逆向选择与流动性外部性的讨论。</li></ul>',6))])}const F=l(p,[["render",D]]);export{_ as __pageData,F as default};
